from marshmallow import Schema, fields

class MySchema(Schema):
    foo = fields.String()

try:
    result = MySchema(unknown="badval")
    print("No error, unknown =", repr(result.unknown))
except ValueError as e:
    print("ValueError:", e)

from marshmallow.utils import get_func_args

class ExampleClass:
    def __init__(self, attr1, attr2):
        pass

args = get_func_args(ExampleClass)
print(args)

from marshmallow import Schema, fields

class BadUserSchema(Schema):
    name = fields.String

try:
    BadUserSchema().dump({"name": "foo"})
except TypeError as e:
    print(str(e))

from marshmallow import utils

try:
    result = utils.from_timestamp(9223372036854775)
    print("Result:", result)
except ValueError as exc:
    print("ValueError:", exc)
except OverflowError as exc:
    print("OverflowError:", exc)
